import clsx from 'clsx';
import dynamic from 'next/dynamic';
import type { RenderProps, Token } from 'prism-react-renderer';
import React, { useMemo } from 'react';
import { Tooltip } from '@/components/Tooltip';
import type { CodeBlockStyle, Highlight } from '../../CodeBlock';

const MarkdownContent = dynamic(async () => import('@/components/MarkdownContent').then((mod) => mod.MarkdownContent), {
  ssr: false,
});

type HighlightedTokens = {
  start: number;
  end: number;
  highlight: Highlight;
};

type TokensWithHighlights = {
  tokens: Token[];
  type: 'default' | 'highlighted';
  highlight?: Highlight;
};

type CodeBlockLineProps = {
  line: Token[];
  highlights?: Highlight[];
  lineNumber: number;
  showLineNumber: boolean;
  lineNumberColorClassName: string;
  lineNumberBgClassName: string;
  isTerminal: boolean;
  animateTokenHighlights?: boolean;
  codeBlockStyle: CodeBlockStyle;
} & Pick<RenderProps, 'getLineProps' | 'getTokenProps'>;

export const CodeBlockLine = ({
  line,
  highlights = [],
  lineNumber,
  getLineProps,
  getTokenProps,
  showLineNumber,
  lineNumberColorClassName,
  lineNumberBgClassName,
  isTerminal,
  animateTokenHighlights = false,
  codeBlockStyle,
}: CodeBlockLineProps) => {
  const lineProps = getLineProps({ line, key: lineNumber });

  // collect highlighted tokens, if there are any
  const highlightedTokens: HighlightedTokens[] = useMemo(() => {
    const highlightedTokensArr: HighlightedTokens[] = [];
    highlights.forEach((highlight) => {
      const highlightText = highlight.text;
      if (!highlightText) {
        return;
      }
      let startIndex: number | undefined;
      let currentPositionInHighlightedText = 0;
      let endIndex = 0;
      const found = line.some((token, tokenIndex) => {
        if (token.empty || !token.content.length) {
          startIndex = undefined;
          currentPositionInHighlightedText = 0;
          return false;
        }
        const startNotSet = startIndex === undefined;
        // trim the start of the script if the start
        // of the highlight hasn't been found yet
        const tokenContent = startNotSet ? token.content.trimStart() : token.content;
        if (!tokenContent.length && startNotSet) {
          return false;
        }
        const comparisonLength = Math.min(tokenContent.length, highlightText.substring(currentPositionInHighlightedText).length);
        const nextPositionInHighlightedText = currentPositionInHighlightedText + comparisonLength;

        const canHighlight =
          !highlightedTokensArr.length || !highlightedTokensArr.some((token) => tokenIndex >= token.start && tokenIndex <= token.end);

        const isMatching =
          tokenContent.substring(0, comparisonLength) === highlightText.substring(currentPositionInHighlightedText, nextPositionInHighlightedText);

        if (isMatching && canHighlight) {
          if (startNotSet) {
            startIndex = tokenIndex;
          }
          currentPositionInHighlightedText = nextPositionInHighlightedText;
        }

        if (currentPositionInHighlightedText === highlight.text?.length) {
          // matching text was found, break loop
          endIndex = tokenIndex;
          const trimmedContent = token.content.trimEnd();
          const endingSpacesLength = token.content.length - trimmedContent.length;
          if (endingSpacesLength) {
            line.splice(tokenIndex + 1, 0, {
              content: new Array(endingSpacesLength).fill(' ').join(''),
              types: ['plain'],
            });
            token.content = trimmedContent;
          }
          return true;
        }

        return false;
      });

      if (found && startIndex !== undefined) {
        highlightedTokensArr.push({
          start: startIndex,
          end: endIndex,
          highlight,
        });
      }
    });

    // sort highlighted tokens by their start position
    highlightedTokensArr.sort((tokensA, tokensB) => {
      if (tokensA.start < tokensB.start) {
        return -1;
      }

      return tokensA.start > tokensB.start ? 1 : 0;
    });

    return highlightedTokensArr;
  }, [highlights, line]);

  // if there are highlighted tokens, split tokens in the
  // line by segments of not highlighted and highlighted token
  // if there are no highlighted tokens, the line is used as-is.
  const transformedLine: TokensWithHighlights[] = useMemo(() => {
    if (!highlightedTokens.length) {
      return [
        {
          tokens: line,
          type: 'default',
        },
      ];
    }
    const transformedLineArr: TokensWithHighlights[] = [];

    let lastIndex = 0;
    // go through highlighted tokens to add the segments before/after to the
    // transformLineArr array
    highlightedTokens.forEach((highlightedTokensItem, index) => {
      if (lastIndex < highlightedTokensItem.start) {
        transformedLineArr.push({
          tokens: line.slice(lastIndex, highlightedTokensItem.start),
          type: 'default',
        });
      }
      // check if the start text should be trimmed
      const targetToken = line[highlightedTokensItem.start];
      if (!targetToken) {
        return;
      }
      const token: Token = { ...targetToken };
      if (token.content.startsWith(' ') && !highlightedTokensItem.highlight.text?.startsWith(' ')) {
        const originalLength = token.content.length;
        token.content = token.content.trimStart();
        // push the spaces as a separate token
        // so that they won't be highlighted.
        transformedLineArr.push({
          tokens: [
            {
              content: ' '.repeat(originalLength - token.content.length),
              types: ['plain'],
            },
          ],
          type: 'default',
        });
      }
      transformedLineArr.push({
        tokens: [token, ...line.slice(highlightedTokensItem.start + 1, highlightedTokensItem.end + 1)],
        type: 'highlighted',
        highlight: highlightedTokensItem.highlight,
      });
      lastIndex = highlightedTokensItem.end + 1;

      // if this is the last item in `highlightedTokens` and
      // its end index is less than the line's length, that means
      // there are tokens at the end of the line that aren't highlighted
      // and should be pushed as-is to the `transformLineArr` array.
      if (index === highlightedTokens.length - 1 && lastIndex < line.length - 1) {
        transformedLineArr.push({
          tokens: line.slice(lastIndex),
          type: 'default',
        });
      }
    });

    return transformedLineArr;
  }, [highlightedTokens, line.slice, line.length, line]);

  const getTokensElm = ({ tokens, isTokenHighlighted, offset }: { tokens: Token[]; isTokenHighlighted: boolean; offset: number }) => (
    <span className={clsx(isTokenHighlighted && 'relative group')} data-testid="code-block-line-tokens">
      {isTokenHighlighted && (
        <span
          className={clsx(
            'absolute left-0 z-0',
            codeBlockStyle === 'loud' && [
              'top-0 h-full',
              'lg:bg-cms-alpha-white-alpha-6 lg:border lg:border-cms-alpha-white-alpha-12',
              'lg:rounded-docs_xs scale-x-[1.05]',
              animateTokenHighlights && ['animate-fast animate-growWidth animation-fill-forwards'],
              !animateTokenHighlights && 'w-full',
            ],
            codeBlockStyle === 'subtle' && [
              'bottom-0 w-full h-full scale-y-[0.1] transition-transform origin-bottom',
              'group-hover:scale-y-100 bg-cms-fg-base',
            ],
          )}
          data-testid="code-block-line-highlight"
        />
      )}
      {tokens.map((token, key) => {
        const tokenKey = offset + key;
        const { className: tokenClassName, ...rest } = getTokenProps({
          token,
          key: tokenKey,
        });
        return (
          <span
            key={tokenKey}
            className={clsx(
              tokenClassName,
              isTokenHighlighted && [
                'relative z-[1]',
                codeBlockStyle === 'subtle' && 'group-hover:!text-cms-fg-on-color group-hover:dark:!text-cms-fg-on-inverted',
              ],
            )}
            data-testid="code-block-line-token"
            {...rest}
          />
        );
      })}
    </span>
  );

  const isHighlightedLine = useMemo(() => highlights.length !== 0 && highlightedTokens.length === 0, [highlights, highlightedTokens]);

  return (
    <span
      key={lineNumber}
      {...lineProps}
      className={clsx('table-row', isHighlightedLine && 'bg-cms-alpha-white-alpha-6', lineProps.className)}
      data-testid="code-block-line"
    >
      {(showLineNumber || isTerminal) && (
        <span
          className={clsx(
            'mr-docs_1 table-cell select-none',
            'sticky left-0 w-[1%] px-docs_1 text-right',
            lineNumberColorClassName,
            lineNumberBgClassName,
          )}
          data-testid="line-number"
        >
          {isTerminal ? '❯' : showLineNumber ? lineNumber + 1 : ''}
        </span>
      )}
      <span>
        {transformedLine.map(({ tokens, type, highlight }, index) => {
          const offset = index === 0 ? 0 : (transformedLine[index - 1]?.tokens.length ?? 0);
          const tooltipText =
            highlight?.tooltipText || (isHighlightedLine ? highlights.find((h) => h.tooltipText !== undefined)?.tooltipText : undefined);
          const isHighlighted = type === 'highlighted';
          return (
            <React.Fragment key={index}>
              {tooltipText && (
                <Tooltip
                  text={tooltipText}
                  tooltipClassName="font-base"
                  render={({ content }) => (
                    <MarkdownContent allowedElements={['a', 'strong', 'code', 'br']} unwrapDisallowed={true}>
                      {typeof content === 'string' ? content : ''}
                    </MarkdownContent>
                  )}
                >
                  {getTokensElm({
                    tokens,
                    isTokenHighlighted: isHighlighted,
                    offset,
                  })}
                </Tooltip>
              )}
              {!tooltipText &&
                getTokensElm({
                  tokens,
                  isTokenHighlighted: isHighlighted,
                  offset,
                })}
            </React.Fragment>
          );
        })}
      </span>
    </span>
  );
};
