'use client';

import type { Ref } from '@cms/types';
import clsx from 'clsx';
import type React from 'react';
import { useCallback, useEffect, useRef } from 'react';
import type { ButtonProps } from '@/components/Button';
import { useKeyboardShortcut } from '@/hooks/use-keyboard-shortcut';
import { useModal } from '@/providers/Modal';
import { ModalFooter } from './Footer';
import { ModalHeader } from './Header';

export type ModalProps = {
  className?: string;
  title?: React.ReactNode;
  actions?: ButtonProps[];
  modalContainerClassName?: string;
  contentClassName?: string;
  onClose?: React.ReactEventHandler<HTMLDialogElement>;
  open?: boolean;
  footerContent?: React.ReactNode;
  passedRef?: Ref<HTMLDialogElement>;
  headerClassName?: string;
} & Omit<React.ComponentProps<'dialog'>, 'ref' | 'title' | 'key'>;

export const Modal = ({
  className,
  title,
  actions,
  children,
  contentClassName,
  modalContainerClassName,
  onClose,
  open = true,
  footerContent,
  passedRef,
  ...props
}: ModalProps) => {
  const { closeModal } = useModal();
  const ref = useRef<HTMLDialogElement | null>(null);

  const setRefs = useCallback(
    (node: HTMLDialogElement) => {
      // Ref's from useRef needs to have the node assigned to `current`
      ref.current = node;
      if (typeof passedRef === 'function') {
        passedRef(node);
      } else if (passedRef && 'current' in passedRef) {
        passedRef.current = node;
      }
    },
    [passedRef],
  );

  useKeyboardShortcut({
    metakey: false,
    checkEditing: false,
    shortcutKeys: ['escape'],
    action: () => {
      if (open) {
        ref.current?.close();
      }
    },
  });

  const handleClick = (e: React.MouseEvent<HTMLDialogElement, MouseEvent>) => {
    // close modal when the user clicks outside the content
    if (e.target === ref.current) {
      closeModal();
      onClose?.(e);
    }
  };

  const handleClose = (e: React.SyntheticEvent<HTMLDialogElement, Event>) => {
    onClose?.(e);
    closeModal();
  };

  useEffect(() => {
    if (open) {
      document.body.setAttribute('data-modal', 'opened');
    } else {
      document.body.removeAttribute('data-modal');
    }
  }, [open]);

  return (
    <dialog
      {...props}
      className={clsx(
        'fixed top-0 left-0 flex h-screen w-screen items-center justify-center',
        'bg-cms-bg-overlay z-[499]',
        'hidden open:flex border-0 px-docs_0.5 lg:p-0',
        className,
      )}
      onClick={handleClick}
      ref={setRefs}
      onClose={handleClose}
      open={open}
    >
      <div
        className={clsx(
          'bg-cms-bg-base rounded-docs_lg',
          'shadow-elevation-modal dark:shadow-elevation-modal-dark',
          'max-w-full sm:max-w-modal-sm md:max-w-modal-md lg:max-w-modal-lg',
          'h-auto w-full',
          modalContainerClassName,
        )}
        data-testid="modal-container"
      >
        {title && <ModalHeader title={title} />}
        <div className={clsx('overflow-auto py-docs_1.5 px-docs_2 rounded-docs_lg', contentClassName)} data-testid="modal-content">
          {children}
        </div>
        {actions && actions?.length > 0 && <ModalFooter actions={actions} />}
        {footerContent && <ModalFooter>{footerContent}</ModalFooter>}
      </div>
    </dialog>
  );
};
